[asy]
unitsize(2 cm);

pair A, B, C, Ap, Bp, Cp, O;

O = (0,0);
A = dir(210);
B = dir(60);
C = dir(330);
Ap = dir(15);
Bp = dir(270);
Cp = dir(135);

draw(Circle(O,1));
draw(A--B--C--cycle);
draw((B + C)/2--Ap);
draw((A + C)/2--Bp);
draw((A + B)/2--Cp);

label("$A$", A, A);
label("$B$", B, B);
label("$C$", C, C);
label("$A'$", Ap, Ap);
label("$B'$", Bp, Bp);
label("$C'$", Cp, Cp);
[/asy]

overview.gold_answer:
Note that the perpendicular bisectors meet at $O,$ the circumcenter of triangle $ABC.$

[asy]
