\begin{align*}
\frac{\sin 18^\circ \cos 12^\circ + \cos 18^\circ \sin 12^\circ}{\sin 22^\circ \cos 8^\circ + \cos 22^\circ \sin 8^\circ} &= \frac{\sin (18^\circ + 12^\circ)}{\sin (22^\circ + 8^\circ)} \\
